"""Checks the committed sample documents: regenerated byte for byte, watermark on every PDF page, values from inputs.json.

Run: python3 -m unittest discover -s data/sample-docs -p 'test_*.py'
"""

from __future__ import annotations

import json
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO = HERE.parent.parent
sys.path.insert(0, str(HERE))
import make_sample_docs as m  # noqa: E402

PDFS = ["sample-epd-mix-a.pdf", "sample-epd-mix-b.pdf"]
PNGS = ["delivery-ticket-P-001.png", "delivery-ticket-P-002.png"]


def pdftotext(path: Path, page: int | None = None) -> str:
    args = ["pdftotext"] + (["-f", str(page), "-l", str(page)] if page else []) + [str(path), "-"]
    return subprocess.run(args, check=True, capture_output=True, text=True).stdout


def pages(path: Path) -> int:
    info = subprocess.run(["pdfinfo", str(path)], check=True, capture_output=True, text=True).stdout
    return int(next(l.split()[1] for l in info.splitlines() if l.startswith("Pages:")))


class SampleDocs(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.tmp = tempfile.TemporaryDirectory()
        cls.out = Path(cls.tmp.name)
        subprocess.run([sys.executable, str(HERE / "make_sample_docs.py"), "--out", str(cls.out)], check=True, capture_output=True)
        cls.inputs = json.loads((REPO / "data" / "scenario" / "inputs.json").read_text("utf8"))

    @classmethod
    def tearDownClass(cls) -> None:
        cls.tmp.cleanup()

    def test_committed_files_match_the_generator(self) -> None:
        for name in PDFS + PNGS:
            with self.subTest(name=name):
                self.assertEqual((HERE / name).read_bytes(), (self.out / name).read_bytes(), f"{name}: re-run make_sample_docs.py")

    def test_every_pdf_page_carries_the_watermark_as_text(self) -> None:
        for name in PDFS:
            n = pages(HERE / name)
            self.assertGreaterEqual(n, 1)
            for p in range(1, n + 1):
                with self.subTest(name=name, page=p):
                    self.assertIn(m.WATERMARK, pdftotext(HERE / name, p))

    def test_gwp_lines_come_from_inputs_and_read_back_in_one_line(self) -> None:
        for key, meta in m.EPD_META.items():
            mix = self.inputs["mixes"][key]
            text = pdftotext(HERE / meta["file"])
            lo, hi = mix["gwp_total_kg_per_m3"]
            with self.subTest(mix=key):
                self.assertIn(f"GWP-total, modules A1-A3: {lo} to {hi} kg CO2e per m3 of concrete.", text)
                self.assertIn(meta["code"], text)
                self.assertIn(f"{mix['cement_kg_per_m3']} kg per m3 [1]", text)
                self.assertIn("NRMCA EPD No. 20243", text)
                self.assertIn("fictional", text)

    def test_tickets_are_images_of_the_expected_size(self) -> None:
        from PIL import Image

        for name in PNGS:
            with self.subTest(name=name), Image.open(HERE / name) as im:
                self.assertEqual(im.format, "PNG")
                self.assertEqual(im.size, (1080, 1440))

    def test_ticket_values_come_from_inputs(self) -> None:
        for label, pour in self.inputs["pours"].items():
            with self.subTest(pour=label):
                self.assertEqual(pour["ticket"]["mix_code"], m.EPD_META[pour["delivered_mix"]]["code"])
                self.assertIn("fictional", pour["ticket"]["supplier"])
                self.assertEqual(pour["ticket_doc"], f"data/sample-docs/delivery-ticket-{label}.png")
        for key, meta in m.EPD_META.items():
            self.assertEqual(self.inputs["mixes"][key]["mix_code"], meta["code"])
            self.assertEqual(self.inputs["mixes"][key]["epd_doc"], f"data/sample-docs/{meta['file']}")

if __name__ == "__main__":
    unittest.main()
